@props(['paginator'])
@if($paginator->hasPages())<nav aria-label="Paginación"><ul class="z-pagination"><li>@if($paginator->onFirstPage())<span aria-disabled="true">‹</span>@else<a href="{{ $paginator->previousPageUrl() }}" rel="prev" aria-label="Página anterior">‹</a>@endif</li>@foreach($paginator->getUrlRange(max(1,$paginator->currentPage()-2),min($paginator->lastPage(),$paginator->currentPage()+2)) as $page=>$url)<li><a href="{{ $url }}" @if($page===$paginator->currentPage()) aria-current="page" @endif>{{ $page }}</a></li>@endforeach<li>@if($paginator->hasMorePages())<a href="{{ $paginator->nextPageUrl() }}" rel="next" aria-label="Página siguiente">›</a>@else<span aria-disabled="true">›</span>@endif</li></ul></nav>@endif
